WITH RECURSIVE nums(x) AS (
  SELECT 2 WHERE 2 < (SELECT n FROM params)
  UNION ALL
  SELECT x + 1 FROM nums WHERE x + 1 < (SELECT n FROM params)
),
primes(p) AS (
  SELECT x FROM nums
  WHERE NOT EXISTS (
    SELECT 1 FROM nums d WHERE d.x > 1 AND d.x < nums.x AND nums.x % d.x = 0
  )
)
SELECT GROUP_CONCAT(p, ' ') FROM primes;
